#:property ImportDirectoryBuildProps=false
#:property ImportDirectoryPackagesProps=false
#:property ImportDirectoryBuildTargets=false
#:property NuGetAudit=false
#:property PublishAot=false

// Generates the C# classes of the Wayland protocols the Linux platform speaks — the
// managed counterpart of wayland-scanner's client header and glue code.
//
//     dotnet run tools/wayland-scanner.cs
//     dotnet run tools/wayland-scanner.cs -- --check   — fail if a generated file is stale
//
// Every <name>.xml in src/ZeppelinForms.Linux/Wayland/Protocols becomes <name>.g.cs next
// to it. The output is checked in, as wayland-scanner's is in C projects: a build needs
// no generator, and a change to a protocol shows up in review as code.
//
// What is generated, per interface:
//   * a sealed class over WlProxy with a method per request — a new_id comes back as
//     the new object, a destructor destroys the proxy after it is sent;
//   * a C# event per protocol event, decoded from libwayland's arguments;
//   * the enums, and the message tables WlInterface hands to libwayland.

using System.Text;
using System.Xml.Linq;

bool check = args.Contains("--check");

string root = FindRoot();
string folder = Path.Combine(root, "src", "ZeppelinForms.Linux", "Wayland", "Protocols");

int stale = 0;

foreach (string xml in Directory.GetFiles(folder, "*.xml").OrderBy(f => f, StringComparer.Ordinal))
{
    string output = Path.ChangeExtension(xml, ".g.cs");
    string code = Generate(XDocument.Load(xml), Path.GetFileNameWithoutExtension(xml));

    string? existing = File.Exists(output) ? File.ReadAllText(output) : null;

    if (existing == code) continue;

    if (check)
    {
        Console.Error.WriteLine($"stale: {Path.GetRelativePath(root, output)}");
        stale++;
        continue;
    }

    File.WriteAllText(output, code);
    Console.WriteLine($"wrote {Path.GetRelativePath(root, output)}");
}

return stale == 0 ? 0 : 1;

static string FindRoot()
{
    for (string? dir = Directory.GetCurrentDirectory(); dir is not null; dir = Path.GetDirectoryName(dir))
        if (Directory.Exists(Path.Combine(dir, "src", "ZeppelinForms.Linux")))
            return dir;

    throw new InvalidOperationException("Run from inside the repository.");
}

static string Generate(XDocument document, string fileName)
{
    var protocol = document.Root!;
    var interfaces = protocol.Elements("interface").ToList();

    var sb = new StringBuilder();

    sb.AppendLine("// <auto-generated>");
    sb.AppendLine($"// Generated by tools/wayland-scanner.cs from {fileName}.xml — do not edit.");
    sb.AppendLine("// </auto-generated>");
    sb.AppendLine("#nullable enable");
    sb.AppendLine("#pragma warning disable CS1591");
    sb.AppendLine();
    sb.AppendLine("namespace ZeppelinForms.Linux.Wayland;");
    sb.AppendLine();

    // the tables of the whole file, defined together: their types point at each other
    sb.AppendLine($"internal static class {Pascal(fileName)}Protocol");
    sb.AppendLine("{");
    sb.AppendLine("    public static void Define()");
    sb.AppendLine("    {");

    foreach (var iface in interfaces)
    {
        string name = (string)iface.Attribute("name")!;
        sb.AppendLine($"        WlInterface.Define(\"{name}\", {(string)iface.Attribute("version")!},");
        sb.AppendLine($"            [{string.Join(", ", iface.Elements("request").Select(MessageLiteral))}],");
        sb.AppendLine($"            [{string.Join(", ", iface.Elements("event").Select(MessageLiteral))}]);");
    }

    sb.AppendLine("    }");
    sb.AppendLine("}");

    foreach (var iface in interfaces)
    {
        sb.AppendLine();
        Interface(sb, iface);
    }

    return sb.ToString().ReplaceLineEndings("\n");
}

static string MessageLiteral(XElement message)
{
    var signature = new StringBuilder();
    var types = new List<string>();

    if (message.Attribute("since") is { } since)
        signature.Append((string)since);

    foreach (var arg in message.Elements("arg"))
    {
        string type = (string)arg.Attribute("type")!;
        string? iface = (string?)arg.Attribute("interface");

        if ((string?)arg.Attribute("allow-null") == "true")
            signature.Append('?');

        // a new_id of no interface — wl_registry.bind — is sent as its interface's name,
        // the version and the id
        if (type == "new_id" && iface is null)
        {
            signature.Append("sun");
            types.AddRange(["null", "null", "null"]);
            continue;
        }

        signature.Append(type switch
        {
            "int" => 'i',
            "uint" => 'u',
            "fixed" => 'f',
            "string" => 's',
            "object" => 'o',
            "new_id" => 'n',
            "array" => 'a',
            "fd" => 'h',
            _ => throw new InvalidOperationException($"unknown argument type {type}"),
        });

        types.Add(iface is null ? "null" : $"\"{iface}\"");
    }

    return $"new(\"{(string)message.Attribute("name")!}\", \"{signature}\", [{string.Join(", ", types)}])";
}

static void Interface(StringBuilder sb, XElement iface)
{
    string name = (string)iface.Attribute("name")!;
    string version = (string)iface.Attribute("version")!;
    string cls = Pascal(name);
    bool isDisplay = name == "wl_display";

    var requests = iface.Elements("request").ToList();
    var events = iface.Elements("event").ToList();

    var requestNames = requests.Select(r => Pascal((string)r.Attribute("name")!)).ToHashSet();
    var eventNames = new HashSet<string>();

    Summary(sb, iface, "");
    sb.AppendLine($"internal sealed unsafe partial class {cls} : WlProxy, IWlObject<{cls}>");
    sb.AppendLine("{");
    sb.AppendLine($"    public static string InterfaceName => \"{name}\";");
    sb.AppendLine($"    public static uint InterfaceVersion => {version};");
    sb.AppendLine();

    // the display is libwayland's own: it listens to its events itself
    sb.AppendLine($"    private {cls}(nint handle) : base(handle{(isDisplay ? ", listen: false" : "")}) {{ }}");
    sb.AppendLine();
    sb.AppendLine($"    public static {cls} Wrap(nint handle) => new(handle);");

    // ===== enums =====

    foreach (var e in iface.Elements("enum"))
    {
        string enumName = Pascal((string)e.Attribute("name")!);

        if (requestNames.Contains(enumName) || events.Any(ev => Pascal((string)ev.Attribute("name")!) == enumName))
            enumName += "Kind";

        sb.AppendLine();
        Summary(sb, e, "    ");

        if ((string?)e.Attribute("bitfield") == "true")
            sb.AppendLine("    [System.Flags]");

        sb.AppendLine($"    public enum {enumName} : uint");
        sb.AppendLine("    {");

        foreach (var entry in e.Elements("entry"))
        {
            string entryName = Pascal((string)entry.Attribute("name")!);
            if (char.IsDigit(entryName[0])) entryName = "_" + entryName;

            sb.AppendLine($"        {entryName} = {(string)entry.Attribute("value")!},");
        }

        sb.AppendLine("    }");
    }

    // ===== requests =====

    for (uint opcode = 0; opcode < requests.Count; opcode++)
        Request(sb, requests[(int)opcode], opcode);

    // ===== events =====

    var decoded = new List<(uint Opcode, string Name, List<(string Type, string Decode)> Args, bool Destructor)>();

    for (uint opcode = 0; opcode < events.Count; opcode++)
    {
        var ev = events[(int)opcode];
        string evName = Pascal((string)ev.Attribute("name")!);

        if (requestNames.Contains(evName) || evName is "Dispatch" or "Wrap" or "Version" or "Handle")
            evName += "Event";

        eventNames.Add(evName);

        var args = new List<(string Type, string Decode)>();
        int slot = 0;

        foreach (var arg in ev.Elements("arg"))
        {
            string type = (string)arg.Attribute("type")!;
            string? argIface = (string?)arg.Attribute("interface");
            bool nullable = (string?)arg.Attribute("allow-null") == "true";
            string a = $"a[{slot}]";

            args.Add(type switch
            {
                "int" => ("int", $"{a}.I"),
                "uint" => ("uint", $"{a}.U"),
                "fixed" => ("double", $"{a}.I / 256.0"),
                "fd" => ("int", $"{a}.I"),
                "string" => (nullable ? "string?" : "string", nullable ? $"Text({a}.P)" : $"Text({a}.P)!"),
                "array" => ("byte[]", $"Bytes({a}.P)"),
                "object" when argIface is not null => ($"{Pascal(argIface)}?", $"FromHandle<{Pascal(argIface)}>({a}.P)"),
                "object" => ("WlProxy?", $"FromHandle<WlProxy>({a}.P)"),
                "new_id" when argIface is not null => (Pascal(argIface), $"{Pascal(argIface)}.Wrap({a}.P)"),
                _ => throw new InvalidOperationException($"event argument {type} without an interface"),
            });

            slot++;
        }

        sb.AppendLine();
        Summary(sb, ev, "    ");

        string signature = args.Count == 0 ? "System.Action" : $"System.Action<{string.Join(", ", args.Select(x => x.Type))}>";
        sb.AppendLine($"    public event {signature}? {evName};");

        decoded.Add((opcode, evName, args, (string?)ev.Attribute("type") == "destructor"));
    }

    sb.AppendLine();
    sb.AppendLine("    protected override void Dispatch(uint opcode, WlArgument* a)");
    sb.AppendLine("    {");

    if (decoded.Count > 0)
    {
        sb.AppendLine("        switch (opcode)");
        sb.AppendLine("        {");

        foreach (var (opcode, evName, args, destructor) in decoded)
        {
            sb.AppendLine($"            case {opcode}:");
            sb.AppendLine($"                {evName}?.Invoke({string.Join(", ", args.Select(x => x.Decode))});");

            // the server destroyed the object with this event: the proxy goes too
            if (destructor)
                sb.AppendLine("                DestroyProxy();");

            sb.AppendLine("                break;");
        }

        sb.AppendLine("        }");
    }

    sb.AppendLine("    }");
    sb.AppendLine("}");
}

static void Request(StringBuilder sb, XElement request, uint opcode)
{
    string name = Pascal((string)request.Attribute("name")!);

    // the members of WlProxy keep their names
    if (name is "Dispatch" or "Wrap" or "Version" or "Handle" or "IsAlive" or "Emit" or "EmitConstructor")
        name += "Request";

    bool destructor = (string?)request.Attribute("type") == "destructor";

    var parameters = new List<string>();
    var fill = new List<string>();
    var cleanup = new List<string>();

    string returnType = "void";
    string? created = null;      // the interface of a typed new_id
    bool generic = false;        // a new_id of no interface: Bind<T>
    string? genericName = null;  // its interface's name argument

    int slot = 0;

    foreach (var arg in request.Elements("arg"))
    {
        string type = (string)arg.Attribute("type")!;
        string? iface = (string?)arg.Attribute("interface");
        bool nullable = (string?)arg.Attribute("allow-null") == "true";
        string argName = Camel((string)arg.Attribute("name")!);
        string a = $"a[{slot}]";

        switch (type)
        {
            case "int":
            case "fd":
                parameters.Add($"int {argName}");
                fill.Add($"{a}.I = {argName};");
                break;

            case "uint":
                parameters.Add($"uint {argName}");
                fill.Add($"{a}.U = {argName};");
                break;

            case "fixed":
                parameters.Add($"double {argName}");
                fill.Add($"{a}.I = (int)System.Math.Round({argName} * 256.0);");
                break;

            case "string":
                parameters.Add($"string{(nullable ? "?" : "")} {argName}");
                fill.Add($"{a}.P = Utf8({argName});");
                cleanup.Add($"Free({a}.P);");
                break;

            case "object":
                parameters.Add($"{(iface is null ? "WlProxy" : Pascal(iface))}{(nullable ? "?" : "")} {argName}");
                fill.Add(nullable ? $"{a}.P = {argName}?.Handle ?? 0;" : $"{a}.P = {argName}.Handle;");
                break;

            case "array":
                parameters.Add($"byte[] {argName}");
                fill.Add($"WlArray {argName}Array = new() {{ Size = (nuint){argName}.Length, Alloc = (nuint){argName}.Length, Data = (nint)System.Runtime.InteropServices.NativeMemory.Alloc((nuint)System.Math.Max(1, {argName}.Length)) }};");
                fill.Add($"{argName}.CopyTo(new System.Span<byte>((void*){argName}Array.Data, {argName}.Length));");
                fill.Add($"{a}.P = (nint)(&{argName}Array);");
                cleanup.Add($"System.Runtime.InteropServices.NativeMemory.Free((void*){argName}Array.Data);");
                break;

            case "new_id" when iface is not null:
                created = iface;
                returnType = Pascal(iface);
                fill.Add($"{a}.U = 0;");
                break;

            case "new_id":
                generic = true;
                returnType = "T";
                parameters.Add("uint version");
                genericName = a;
                fill.Add($"{a}.P = Utf8(T.InterfaceName);");
                fill.Add($"a[{slot + 1}].U = version;");
                fill.Add($"a[{slot + 2}].U = 0;");
                cleanup.Add($"Free({a}.P);");
                slot += 2;
                break;
        }

        slot++;
    }

    sb.AppendLine();
    Summary(sb, request, "    ");

    if (request.Attribute("since") is { } since)
        sb.AppendLine($"    /// <remarks>Since version {(string)since}.</remarks>");

    string generics = generic ? "<T>" : "";
    string constraint = generic ? " where T : WlProxy, IWlObject<T>" : "";

    sb.AppendLine($"    public {returnType} {name}{generics}({string.Join(", ", parameters)}){constraint}");
    sb.AppendLine("    {");

    string args = slot == 0 ? "null" : "a";

    if (slot > 0)
        sb.AppendLine($"        WlArgument* a = stackalloc WlArgument[{slot}];");

    foreach (string line in fill)
        sb.AppendLine($"        {line}");

    string send = generic
        ? $"T.Wrap(EmitConstructor({opcode}, {args}, T.InterfaceName, version))"
        : created is not null
            ? $"{Pascal(created)}.Wrap(EmitConstructor({opcode}, {args}, \"{created}\", Version))"
            : $"Emit({opcode}, {args})";

    string call = returnType == "void" ? $"{send};" : $"var created = {send};";

    if (cleanup.Count > 0)
    {
        sb.AppendLine("        try");
        sb.AppendLine("        {");
        sb.AppendLine($"            {call}");
        if (destructor) sb.AppendLine("            DestroyProxy();");
        if (returnType != "void") sb.AppendLine("            return created;");
        sb.AppendLine("        }");
        sb.AppendLine("        finally");
        sb.AppendLine("        {");
        foreach (string line in cleanup)
            sb.AppendLine($"            {line}");
        sb.AppendLine("        }");
    }
    else
    {
        sb.AppendLine($"        {call}");
        if (destructor) sb.AppendLine("        DestroyProxy();");
        if (returnType != "void") sb.AppendLine("        return created;");
    }

    sb.AppendLine("    }");
}

static void Summary(StringBuilder sb, XElement element, string indent)
{
    string? summary = (string?)element.Element("description")?.Attribute("summary")
        ?? (string?)element.Attribute("summary");

    if (string.IsNullOrWhiteSpace(summary)) return;

    summary = summary.Trim().Replace("&", "&amp;").Replace("<", "&lt;").Replace(">", "&gt;");

    sb.AppendLine($"{indent}/// <summary>{summary}</summary>");
}

static string Pascal(string snake)
{
    var sb = new StringBuilder();

    foreach (string part in snake.Split('_', '-'))
        if (part.Length > 0)
            sb.Append(char.ToUpperInvariant(part[0])).Append(part, 1, part.Length - 1);

    return sb.ToString();
}

static string Camel(string snake)
{
    string pascal = Pascal(snake);
    string camel = char.ToLowerInvariant(pascal[0]) + pascal[1..];

    return camel is "object" or "string" or "interface" or "event" or "fixed" or "class" or "base"
        or "params" or "operator" or "checked" or "default" or "lock" or "out" or "ref" or "in"
        ? "@" + camel
        : camel;
}